#include <bits/stdc++.h>
using namespace std;
int main(){
    long long n;
    while (cin >> n && n != 0) {
        long long s = (long long)floor(sqrt((double)n));
        if (s % 2 == 0) s--;
        if (s < 1) s = 1;
        while (s*s > n) s -= 2;
        while ((s+2)*(s+2) <= n) s += 2;
        long long x = 1, y = s;
        long long rem = n - s*s;
        long long segLen[6] = {1, s, s, 1, s+1, s+1};
        int dx[6] = {0,1,0,1,0,-1};
        int dy[6] = {1,0,-1,0,1,0};
        for (int i = 0; i < 6 && rem > 0; i++) {
            long long take = min(rem, segLen[i]);
            x += dx[i]*take;
            y += dy[i]*take;
            rem -= take;
        }
        cout << x << " " << y << "\n";
    }
}

